use vstd::prelude::*;

verus! {
    fn ones_like<T>(a: &Vec<T>) -> (result: Vec<i32>)
        requires
            a.len() <= u32::MAX as usize, // Ensure the length of the input vector is within bounds
        ensures
            result.len() == a.len() && // The output vector's length matches the input vector's length
            forall|i: nat| 0 <= i < result.len() ==> result[i] == 1 // All elements in the output vector are 1
    {
        let n = a.len() as nat; // Convert the length to a natural number
        let mut result = Vec::new(); // Initialize the output vector

        // Loop invariant:
        // 1. The loop counter `i` is within bounds (0 <= i <= n)
        // 2. The current output length equals the number of iterations completed (result.len() == i)
        // 3. All elements written so far are 1 (forall j: nat | 0 <= j < i ==> result[j] == 1)
        // Decreases clause: n - i (the number of remaining iterations)
        let mut i = 0;
        while i < n
            invariant
                0 <= i <= n,
                result.len() == i,
                forall|j: nat| 0 <= j < i ==> result[j] == 1,
            decreases n - i
        {
            result.push(1); // Append 1 to the output vector
            i = i + 1; // Increment the loop counter
        }

        result // Return the output vector
    }
}

